__mods._test_assert = function(...)
  return __load("test.assert", function(...)
---@type string[]
local arg = {}
--- Node-style assertions. Each one returns normally when its check holds, and
--- otherwise raises an error whose first line is `<name> failed` (plus `: msg`
--- when a message is given), followed by a line saying what was expected and a
--- diff of the two values involved. Errors are raised at the caller's level, so
--- a failure names the spec's line.
--- @class test.assert
--- @overload fun(value: any, msg?: string): any
local M = {}

--- An empty table is not a string list here, because it would print no lines
--- and leave a failure with an empty diff; `vim.inspect` prints it as `{}`.
--- @param value any
--- @return boolean
local function is_string_list(value)
  if type(value) ~= 'table' or #value == 0 or not vim.islist(value) then return false end
  for _, v in ipairs(value) do
    if type(v) ~= 'string' then return false end
  end
  return true
end

--- Turn a value into the lines a failure prints. A string and a list of
--- strings print one entry per line, because `vim.inspect` would put a whole
--- buffer on one line and make its diff useless. Each entry is quoted, so
--- trailing whitespace and a number standing in for a string stay visible.
--- @param value any
--- @return string[]
local function lines_of(value)
  if type(value) == 'string' then
    return vim.tbl_map(vim.inspect, vim.split(value, '\n', { plain = true }))
  end
  if is_string_list(value) then return vim.tbl_map(vim.inspect, value) end
  return vim.split(vim.inspect(value), '\n', { plain = true })
end

--- Build the shortest line diff turning `got` into `want`. Unchanged lines are
--- prefixed with two spaces, deletions with `- `, and insertions with `+ `; a
--- replaced line renders as `-` then `+`.
--- @param got string[]
--- @param want string[]
--- @return string
local function diff(got, want)
  local m, n = #got, #want
  -- `cost[i][j]` is the fewest deletions and insertions turning `got[i..]` into
  -- `want[j..]`. This is Levenshtein distance without its replace move,
  -- because a replaced line prints as a `-` line plus a `+` line and so costs
  -- two lines, not one. The table is built over suffixes, so the walk below
  -- runs forward from the first lines and emits the diff in order.
  -- Integer keys say every cell is written before it is read, which an array
  -- type would make each index re-narrow.
  local cost = {} --- @type table<integer, table<integer, integer>>
  for i = m + 1, 1, -1 do
    cost[i] = {}
    for j = n + 1, 1, -1 do
      if i > m then
        cost[i][j] = n + 1 - j
      elseif j > n then
        cost[i][j] = m + 1 - i
      elseif got[i] == want[j] then
        cost[i][j] = cost[i + 1][j + 1]
      else
        cost[i][j] = 1 + math.min(cost[i + 1][j], cost[i][j + 1])
      end
    end
  end

  local out = { '--- got', '+++ want' }
  local i, j = 1, 1
  while i <= m or j <= n do
    if i <= m and j <= n and got[i] == want[j] then
      out[#out + 1] = '  ' .. got[i]
      i, j = i + 1, j + 1
    elseif j > n or (i <= m and cost[i + 1][j] <= cost[i][j + 1]) then
      -- Deleting first on ties renders a replaced line as `-` then `+`.
      out[#out + 1] = '- ' .. got[i]
      i = i + 1
    else
      out[#out + 1] = '+ ' .. want[j]
      j = j + 1
    end
  end
  return table.concat(out, '\n')
end

--- Raise a failure from an assertion that a spec called directly, so level 3
--- skips both this function and the assertion. Every failure has the same
--- shape: the header, a note saying what was expected, and a diff of `got`
--- against `want`.
--- @param name string
--- @param msg string?
--- @param note string
--- @param got any
--- @param want any
--- @return never
local function fail(name, msg, note, got, want)
  local header = name .. ' failed' .. (msg and (': ' .. msg) or '')
  error(('%s\n%s\n%s'):format(header, note, diff(lines_of(got), lines_of(want))), 3)
end

--- A string and a list of the same lines print alike, and so do `1` and a
--- table holding `1` on one line, so a mismatch in type alone would show a
--- diff with no changed lines. The note names both types.
--- @param got any
--- @param want any
--- @param note string
--- @return string
local function with_types(got, want, note)
  if type(got) == type(want) then return note end
  return ('%s (got a %s, want a %s)'):format(note, type(got), type(want))
end

--- @param value any
--- @param msg? string
--- @return any value
function M.ok(value, msg)
  if not value then fail('ok', msg, 'expected a truthy value', value, true) end
  return value
end

--- Check that `value` is `nil` or `vim.NIL`. Both count, because a `nil`
--- returned from the child arrives in the host as `vim.NIL`: msgpack carries
--- nil as a value, and a Lua table cannot hold `nil`.
--- @param value any
--- @param msg? string
function M.is_nil(value, msg)
  if value == nil or value == vim.NIL then return end
  fail('is_nil', msg, 'expected nil or vim.NIL', value, nil)
end

--- Check identity with `==`, so two tables pass only when they are the same
--- table. Use `deep_equal` to compare contents.
--- @param got any
--- @param want any
--- @param msg? string
function M.equal(got, want, msg)
  if got == want then return end
  local note = with_types(got, want, 'expected the same value')
  if vim.deep_equal(got, want) then
    note = 'expected the same table, got two deep-equal tables (use deep_equal)'
  end
  fail('equal', msg, note, got, want)
end

--- @param got any
--- @param want any
--- @param msg? string
function M.not_equal(got, want, msg)
  if got ~= want then return end
  fail('not_equal', msg, 'expected different values, got the same value twice', got, want)
end

--- @param got any
--- @param want any
--- @param msg? string
function M.deep_equal(got, want, msg)
  if vim.deep_equal(got, want) then return end
  fail('deep_equal', msg, with_types(got, want, 'expected equal contents'), got, want)
end

--- @param got any
--- @param want any
--- @param msg? string
function M.not_deep_equal(got, want, msg)
  if not vim.deep_equal(got, want) then return end
  fail('not_deep_equal', msg, 'expected different contents, got equal ones', got, want)
end

--- @param list any[]
--- @param needle any
--- @return boolean
local function list_has(list, needle)
  for _, v in ipairs(list) do
    if vim.deep_equal(v, needle) then return true end
  end
  return false
end

--- Check that a string holds `needle` as a plain substring, or that a list
--- holds an element deep-equal to `needle`. Substrings are plain because `-`
--- and `+` are pattern quantifiers and are also what specs look for in diffs.
--- @param haystack string|any[]
--- @param needle any
--- @param msg? string
function M.contains(haystack, needle, msg)
  if type(haystack) ~= 'string' and type(haystack) ~= 'table' then
    error('contains: haystack must be a string or a list, got ' .. type(haystack), 2)
  end
  if type(haystack) == 'string' and type(needle) ~= 'string' then
    error('contains: a string haystack needs a string needle, got ' .. type(needle), 2)
  end
  if type(haystack) == 'string' and haystack:find(needle, 1, true) then return end
  if type(haystack) == 'table' and list_has(haystack, needle) then return end
  fail(
    'contains',
    msg,
    'expected the haystack (got) to contain the needle (want)',
    haystack,
    needle
  )
end

--- @param str string
--- @param pattern string  a Lua pattern
--- @param msg? string
function M.matches(str, pattern, msg)
  if type(str) ~= 'string' then error('matches: str must be a string, got ' .. type(str), 2) end
  if str:find(pattern) then return end
  fail('matches', msg, 'expected the string (got) to match the pattern (want)', str, pattern)
end

--- Check that `fn` raises, and return the error. When `expected` is given, the
--- error (inspected first when it is not a string) must hold it as a plain
--- substring.
--- @param fn function
--- @param expected? string
--- @param msg? string
--- @return any err
function M.raises(fn, expected, msg)
  local results = { pcall(fn) }
  if results[1] then
    local returned = { unpack(results, 2) }
    local note = 'expected the function to raise, but it returned (got)'
    fail('raises', msg, note, returned, expected or 'an error')
  end
  local err = results[2]
  if expected == nil then return err end
  local text = type(err) == 'string' and err or vim.inspect(err)
  if text:find(expected, 1, true) then return err end
  fail('raises', msg, 'expected the error (got) to contain the text (want)', text, expected)
end

-- Specs shadow busted's global with `local assert = require('test').assert`,
-- so calling the namespace keeps the built-in `assert(value, msg)` form
-- working. It is `ok`, inlined so `fail`'s level still lands on the spec.
setmetatable(M, {
  __call = function(_, value, msg)
    if not value then fail('ok', msg, 'expected a truthy value', value, true) end
    return value
  end,
})

return M

  end, ...)
end

__mods._test_cli = function(...)
  return __load("test.cli", function(...)
---@type string[]
local arg = {}
--- The `nvim -l <test.lua>` command line: find the spec files, run them, and
--- turn the result into an exit status.
-- Only what parsing and recording need loads here; the runner loads after
-- coverage starts, so a coverage run of this repository counts its lines.
local args = __mods._test_vendor_args("test.vendor.args")
local coverage = __mods._test_coverage("test.coverage")

local M = {}

-- Whether `main` is running. A spec that requires the library during a run
-- executes test/init.lua again, which asks this before starting a second run.
local running = false

--- @return boolean
function M.running() return running end

local USAGE = [[
Usage: nvim -l <test.lua> [<path or glob>...] [options]

Runs spec files. A directory includes every `*_spec.lua` file under it, a file
includes itself, and anything else is a glob matched against paths relative to
the current directory. With no paths, runs `spec/`.

Options:
  --exclude <glob>   Skip paths matching <glob> (repeatable)
  --filter <text>    Run only cases whose full name contains <text>
  --coverage         Report line coverage of lua/**/*.lua, vendor/ excluded,
                     counting lines run in the host and in every child
  --color            Color the output even when stdout is not a terminal
  -h, --help         Show this help

Examples:
  nvim -l lua/myplugin/vendor/test.lua
  nvim -l lua/myplugin/vendor/test.lua spec/ui --filter 'renders'
  nvim -l lua/myplugin/vendor/test.lua 'spec/**/*_spec.lua' --exclude 'spec/slow/**'
]]

--- @type table<string, any>
local ARGS_SPEC = {
  ['--exclude'] = { 'string' },
  ['--filter'] = 'string',
  ['--coverage'] = 'boolean',
  ['--color'] = 'boolean',
  ['--help'] = 'boolean',
  ['-h'] = '--help',
}

--- @param glob string
--- @return vim.lpeg.Pattern
local function compile(glob)
  local ok, pattern = pcall(vim.glob.to_lpeg, glob)
  if not ok then error(('invalid glob %q: %s'):format(glob, pattern), 0) end
  return pattern
end

--- @param path string
--- @param patterns vim.lpeg.Pattern[]
--- @return boolean
local function matches_any(path, patterns)
  for _, pattern in ipairs(patterns) do
    if pattern:match(path) then return true end
  end
  return false
end

--- Every file under `dir`, as paths that start with `dir`.
--- @param dir string
--- @return string[]
local function files_under(dir)
  local out = {}
  -- math.huge is unbounded, but emmylua types `depth` as integer.
  --- @diagnostic disable-next-line: param-type-mismatch
  for rel, kind in vim.fs.dir(dir, { depth = math.huge }) do
    if kind == 'file' then out[#out + 1] = vim.fs.joinpath(dir, rel) end
  end
  return out
end

--- The directory a glob's matches must live under: its path up to the first
--- segment that holds a wildcard.
--- @param glob string
--- @return string
local function glob_root(glob)
  local fixed = {}
  for segment in glob:gmatch '[^/]+' do
    if segment:find '[%*%?%[{]' then break end
    fixed[#fixed + 1] = segment
  end
  return #fixed == 0 and '.' or table.concat(fixed, '/')
end

--- Expand each include into spec files, drop the excluded ones, and return
--- the rest sorted and without duplicates.
--- @param includes string[]
--- @param excludes vim.lpeg.Pattern[]
--- @return string[]
local function find_specs(includes, excludes)
  local found = {} --- @type table<string, true>
  local function add(path)
    path = vim.fs.normalize(path)
    if not matches_any(path, excludes) then found[path] = true end
  end

  for _, include in ipairs(includes) do
    if vim.fn.filereadable(include) == 1 then
      add(include)
    else
      -- A directory means the spec files under it.
      local glob = vim.fn.isdirectory(include) == 1
          and vim.fs.joinpath(vim.fs.normalize(include), '**/*_spec.lua')
        or include
      local pattern = compile(glob)
      for _, path in ipairs(files_under(glob_root(glob))) do
        if pattern:match(vim.fs.normalize(path)) then add(path) end
      end
    end
  end

  local paths = vim.tbl_keys(found)
  table.sort(paths)
  return paths
end

--- The plugin's own sources: every Lua file under `lua/`, except vendored
--- files, which belong to another project.
--- @return string[]
local function coverage_paths()
  if vim.fn.isdirectory 'lua' == 0 then return {} end
  local paths = vim.tbl_filter(
    function(path) return path:match '%.lua$' and not path:find('/vendor/', 1, true) end,
    vim.tbl_map(vim.fs.normalize, files_under 'lua')
  )
  table.sort(paths)
  return paths
end

--- Run the command line `argv` and return the process's exit status.
--- @param argv string[]
--- @return integer
function M.main(argv)
  running = true
  local ok, parsed = pcall(args.parse, ARGS_SPEC, argv)
  if not ok then
    io.stderr:write('test: ', tostring(parsed), '\n\n', USAGE)
    return 2
  end
  if parsed['--help'] then
    io.stdout:write(USAGE)
    return 0
  end

  -- Specs require the plugin's own modules, which live under `lua/` in the
  -- directory the run starts from.
  package.path = 'lua/?.lua;lua/?/init.lua;' .. package.path

  local includes = #parsed._ > 0 and parsed._ or { 'spec' }
  local found_ok, paths = pcall(
    function() return find_specs(includes, vim.tbl_map(compile, parsed['--exclude'] or {})) end
  )
  if not found_ok then
    io.stderr:write('test: ', tostring(paths), '\n')
    return 2
  end
  if #paths == 0 then
    io.stderr:write('test: no spec files matched ', table.concat(includes, ' '), '\n')
    return 1
  end

  -- Escape codes help a person at a terminal and clutter a pipe or a log, so
  -- they are on only for a terminal, unless --color asks for them anyway.
  local paint = __mods._test_color("test.color")(parsed['--color'] or vim.uv.guess_handle(1) == 'tty')

  if parsed['--coverage'] then coverage.start() end
  local report = __mods._test_runner("test.runner").run(paths, { filter = parsed['--filter'], paint = paint })
  if parsed['--coverage'] then
    local run = coverage.stop()
    coverage.report(run, coverage_paths(), paint)
  end
  return report.counts.failed > 0 and 1 or 0
end

return M

  end, ...)
end

__mods._test_color = function(...)
  return __load("test.color", function(...)
---@type string[]
local arg = {}
--- ANSI styling for the command line's output.

--- @alias test.color.Style 'bold'|'dim'|'red'|'green'|'yellow'

--- @type table<test.color.Style, string>
local CODES = { bold = '1', dim = '2', red = '31', green = '32', yellow = '33' }

--- @alias test.color.Paint fun(style: test.color.Style, text: string): string

--- Return a function that wraps text in a style's escape codes when `enabled`,
--- and returns the text unchanged otherwise.
--- @param enabled boolean
--- @return test.color.Paint
return function(enabled)
  return function(style, text)
    if not enabled then return text end
    return ('\27[%sm%s\27[0m'):format(CODES[style], text)
  end
end

  end, ...)
end

__mods._test_coverage = function(...)
  return __load("test.coverage", function(...)
---@type string[]
local arg = {}
-- `record_lines`, `export_hits`, and `write_at_exit` run inside each process
-- being measured: the host, every child, and every script. Children and
-- scripts do not load this library, so those functions cannot reach a
-- module's locals, and a process's hits live in its global
-- `__test_coverage_hits`: `__test_coverage_hits[source][line]` is true once
-- `line` of the chunk named `source` has run. Only that process's own hook
-- writes the table, and only `export_hits` reads it.
--- @diagnostic disable: global-in-non-module

--- Line coverage without dependencies. A line hook records every line that
--- runs, in the host and in every child editor, and `jit.util` lists the lines
--- that hold code, which is the denominator of each file's percentage.
---
--- A plugin's code mostly runs in other processes: the children and the
--- scripts. Every such process gets its hits back to the host the same way:
--- `argv` installs the hook through `--cmd`, and the process writes its hits
--- into the run's directory as it exits. A process that crashes, or that is
--- still running when the run stops, loses its hits.
local M = {}

--- One process's hits, as `export_hits` lists them: `{ path, lines }` pairs,
--- with each file's absolute path, a shape that survives JSON.
--- @alias test.coverage.Export [string, integer[]][]

--- The open run's directory, from `start` to `stop`; nil when not recording.
--- Each process measured during the run writes one file into it.
--- @type string?
local run_dir

--- The line hook that was installed when the open run started, as
--- `debug.gethook` returns it, so `stop` can put it back. A run nests inside
--- another when a spec runs the CLI with `--coverage` through `Nvim.script`,
--- whose `--cmd` has already installed the outer run's hook.
--- @type [function?, string?, integer?]
local prior_hook = {}

--- Install the line hook in the running editor. The same function runs in the
--- host and, through `--cmd`, in each other process, so it has no upvalues.
local function record_lines()
  _G.__test_coverage_hits = _G.__test_coverage_hits or {}
  local hits = _G.__test_coverage_hits
  -- The type stubs declare only the form that takes a thread first.
  --- @diagnostic disable-next-line: param-type-mismatch
  debug.sethook(function(_, line)
    -- A line hook never fires inside itself.
    -- luacov: disable
    local info = debug.getinfo(2, 'S')
    if not info then return end
    local lines = hits[info.source]
    if not lines then
      lines = {}
      hits[info.source] = lines
    end
    lines[line] = true
    -- luacov: enable
  end, 'l')
end

--- Stop recording in the running editor and list its hits per file. It runs
--- in other processes, so it has no upvalues.
--- @return test.coverage.Export
local function export_hits()
  -- Turning the hook off first keeps it from adding this function's own
  -- source to the table while the loop below walks it.
  debug.sethook()
  -- luacov: disable
  local out = {}
  for source, lines in pairs(_G.__test_coverage_hits) do
    -- A chunk name that starts with `@` names a file, often relative to this
    -- process's cwd, which another process does not know. So the path is made
    -- absolute here, where the cwd is right -- unless the process changed
    -- directory after loading the file. Other chunk names are strings, which
    -- no report row can match.
    if source:sub(1, 1) == '@' then
      local path = vim.fs.normalize(vim.fn.fnamemodify(source:sub(2), ':p'))
      out[#out + 1] = { path, vim.tbl_keys(lines) }
    end
  end
  return out
  -- luacov: enable
end

--- Write the process's hits into `dir` as JSON when it exits, in a file named
--- after its pid, so processes never share a file. `VimLeavePre` covers a
--- child that is stopped and a script that returns. `os.exit` -- under normal
--- circumstances, a script's way to set its exit status -- skips
--- `VimLeavePre`, so the hits are also written just before the real `os.exit`
--- runs. It runs in the process, so it has no upvalues; `export` is
--- `export_hits`, loaded there.
--- @param dir string
--- @param export fun(): test.coverage.Export
local function write_at_exit(dir, export)
  local function write()
    local f = io.open(('%s/%d.json'):format(dir, vim.fn.getpid()), 'w')
    if not f then return end
    f:write(vim.json.encode(export()))
    -- `export` has turned the hook off.
    -- luacov: disable
    f:close()
    -- luacov: enable
  end
  local exit = os.exit
  --- @diagnostic disable-next-line: duplicate-set-field
  os.exit = function(...)
    write()
    -- `write` has turned the hook off.
    -- luacov: disable
    return exit(...)
    -- luacov: enable
  end
  vim.api.nvim_create_autocmd('VimLeavePre', { callback = write })
end

--- A Lua expression that loads `f` from its bytecode. Every byte outside
--- printable ASCII is escaped, so the expression can sit in one argv entry
--- and on one Ex command line.
--- @param f function
--- @return string
local function loader(f)
  local escaped = string
    .dump(f)
    :gsub('[%z%c"\\\128-\255]', function(c) return ('\\%03d'):format(c:byte()) end)
  return ('loadstring("%s")'):format(escaped)
end

--- Start recording lines in the host, and in every process that `argv`
--- instruments from now on.
function M.start()
  prior_hook = { debug.gethook() }
  run_dir = vim.fn.tempname()
  vim.fn.mkdir(run_dir, 'p')
  record_lines()
end

--- The Neovim arguments that record a new process's lines into the open run,
--- or none when not recording. They go before any other argument: `--cmd`
--- runs before the user's config and before a `-l` script's first line, so
--- the hook is in place before any of a plugin's code can load.
--- @return string[]
function M.argv()
  if not run_dir then return {} end
  local chunk = ('lua %s(); %s(%q, %s)'):format(
    loader(record_lines),
    loader(write_at_exit),
    run_dir,
    loader(export_hits)
  )
  return { '--cmd', chunk }
end

--- Stop recording, delete the run's directory, and return every process's
--- hits, the host's included. The hook that was installed before `start`
--- comes back, so an outer run keeps recording, e.g. through this run's report.
--- @return test.coverage.Export[]
function M.stop()
  local dir = assert(run_dir, 'coverage.stop: not recording')
  run_dir = nil
  local run = { export_hits() }
  -- `export_hits` has turned the hook off, and this line turns it back on.
  -- The type stubs declare only the form that takes a thread first.
  -- luacov: disable
  --- @diagnostic disable-next-line: param-type-mismatch
  debug.sethook(unpack(prior_hook))
  -- luacov: enable
  for _, path in ipairs(vim.fn.glob(dir .. '/*.json', true, true)) do
    -- A process killed partway through its write leaves a truncated file,
    -- which does not decode. Losing that one process's hits is better than
    -- failing the whole report.
    local ok, export = pcall(vim.json.decode, table.concat(vim.fn.readfile(path), '\n'))
    if ok and type(export) == 'table' then run[#run + 1] = export end
  end
  vim.fn.delete(dir, 'rf')
  return run
end

--------------------------------------------------------------------------------
-- The report
--------------------------------------------------------------------------------

--- The lines of a file that hold code: every line that some bytecode
--- instruction belongs to, in the main chunk and every function nested in it.
--- Returns nil, and the load error, for a file that does not load.
---
--- A function that ends in `error(...)` never runs the return on its closing
--- `end`, yet the line needs no special case: LuaJIT puts the enclosing
--- function's `FNEW`, which creates the function, on that same line, so the
--- line runs whenever the definition does.
--- @param path string
--- @return table<integer, true>?, string?
local function executable_lines(path)
  local chunk, err = loadfile(path)
  if not chunk then return nil, err end
  local util = require 'jit.util'
  local lines = {}
  --- @param fn function
  local function walk(fn)
    local pc = 1
    while util.funcbc(fn, pc) do
      local line = util.funcinfo(fn, pc).currentline
      if line then lines[line] = true end
      pc = pc + 1
    end
    -- Negative constant indices hold a function's nested prototypes.
    local i = -1
    while true do
      local constant = util.funck(fn, i)
      if constant == nil then break end
      if type(constant) == 'proto' then walk(constant) end
      i = i - 1
    end
  end
  walk(chunk)
  return lines
end

--- The lines between a `-- luacov: disable` line and the next
--- `-- luacov: enable` line, or the end of the file. These are luacov's
--- markers, so code already marked for luacov needs no change. A marker is a
--- whole line, as in luacov, so prose that mentions one, such as this comment,
--- does not count as one.
--- @param path string
--- @return table<integer, true>
local function disabled_lines(path)
  local disabled, off = {}, false
  for i, text in ipairs(vim.fn.readfile(path)) do
    local marker = text:match '^%s*%-%-%s*luacov:%s*(%a+)%s*$'
    if marker == 'disable' then
      off = true
    elseif marker == 'enable' then
      off = false
    elseif off then
      disabled[i] = true
    end
  end
  return disabled
end

--- Union every process's hits per file. One file can run in several
--- processes, and under several chunk names in one process (relative, or
--- absolute), so this is the one place hits are combined.
--- @param run test.coverage.Export[]
--- @return table<string, table<integer, true>>
local function hits_by_path(run)
  local by_path = {}
  for _, export in ipairs(run) do
    for _, entry in ipairs(export) do
      local merged = by_path[entry[1]] or {}
      by_path[entry[1]] = merged
      for _, line in ipairs(entry[2]) do
        merged[line] = true
      end
    end
  end
  return by_path
end

--- Compress sorted line numbers into ranges, such as `3, 7-9`.
--- @param lines integer[]
--- @return string
local function ranges(lines)
  local out = {}
  --- @param first integer
  --- @param last integer
  local function add(first, last)
    out[#out + 1] = first == last and tostring(first) or (first .. '-' .. last)
  end
  local first, last --- @type integer?, integer?
  for _, line in ipairs(lines) do
    if last and line == last + 1 then
      last = line
    else
      if first and last then add(first, last) end
      first, last = line, line
    end
  end
  if first and last then add(first, last) end
  return table.concat(out, ', ')
end

--- Print one row per file: its covered share of executable lines, except the
--- disabled ones, and the
--- lines that never ran, or why the file could not be measured. Then print
--- the total. A fully covered share prints green and a partial one yellow;
--- text is padded before it is painted, so escape codes do not break the
--- columns.
--- @param run test.coverage.Export[]  every process's hits, as `stop` returns them
--- @param paths string[]  the files to report, relative to the cwd
--- @param paint test.color.Paint
function M.report(run, paths, paint)
  local by_path = hits_by_path(run)
  --- @type { name: string, hit: integer, count: integer, note: string, loaded: boolean }[]
  local rows = {}
  local total_hit, total_lines = 0, 0
  for _, path in ipairs(paths) do
    local executable, err = executable_lines(path)
    if not executable then
      rows[#rows + 1] = {
        name = path,
        hit = 0,
        count = 0,
        note = 'did not load: ' .. tostring(err),
        loaded = false,
      }
    else
      for line in pairs(disabled_lines(path)) do
        executable[line] = nil
      end
      local hits = by_path[vim.fs.normalize(vim.fn.fnamemodify(path, ':p'))] or {}
      local missed, hit, count = {}, 0, 0
      for line in pairs(executable) do
        count = count + 1
        if hits[line] then
          hit = hit + 1
        else
          missed[#missed + 1] = line
        end
      end
      table.sort(missed)
      total_hit, total_lines = total_hit + hit, total_lines + count
      local note = #missed > 0 and ('missed: ' .. ranges(missed)) or ''
      rows[#rows + 1] = { name = path, hit = hit, count = count, note = note, loaded = true }
    end
  end
  rows[#rows + 1] =
    { name = 'total', hit = total_hit, count = total_lines, note = '', loaded = true }

  local width = 0
  for _, row in ipairs(rows) do
    width = math.max(width, #row.name)
  end

  io.stdout:write('\n', paint('bold', 'Coverage'), '\n')
  for _, row in ipairs(rows) do
    local share = ('%6.1f%%'):format(row.count == 0 and 100 or row.hit / row.count * 100)
    local style = row.hit == row.count and 'green' or 'yellow' --- @type test.color.Style
    if not row.loaded then
      share, style = '      -', 'red'
    end
    local line = ('  %-' .. width .. 's %s  %d/%d'):format(
      row.name,
      paint(style, share),
      row.hit,
      row.count
    )
    if row.note ~= '' then line = line .. paint('dim', '  ' .. row.note) end
    io.stdout:write(line, '\n')
  end
end

return M

  end, ...)
end

---@param arg string[]
local function __entry(arg, ...)
--- The library's one public surface, and its command line. A bundle built with
--- `nvim-bundle build test` returns this table, so every helper a spec may call
--- is exported here; the other files under `lua/test/` are its implementation.
--- Executed as `nvim -l <this file>`, it runs spec files instead.

--- Whether this file is the script `nvim -l` is executing, rather than a
--- module being required. It reads the plain `arg`, not `_G.arg`: when a spec
--- requires a bundle that is already running, nvim-bundle runs this file again
--- with that `arg` empty, so the check says "module" by itself.
--- @return boolean
local function is_script()
  local info = debug.getinfo(1, 'S')
  local script = arg and arg[0]
  if not info or not script or info.source:sub(1, 1) ~= '@' then return false end
  local this = vim.fs.normalize(vim.fn.fnamemodify(info.source:sub(2), ':p'))
  return this == vim.fs.normalize(vim.fn.fnamemodify(script, ':p'))
end

if is_script() then
  -- A checkout has no `lua/` directory on `package.path`; this file is
  -- `<lua>/test/init.lua`, so `:h:h` is that directory. A bundle inlines its
  -- requires, so the extra path is harmless there.
  -- is_script() returned true, so arg[0] holds this file's path.
  local lua_dir = vim.fn.fnamemodify(arg[0] --[[@as string]], ':p:h:h')
  package.path = ('%s/?.lua;%s/?/init.lua;%s'):format(lua_dir, lua_dir, package.path)

  -- The script hands off to the command line before loading anything else, so
  -- a coverage run starts recording before the library's other modules load.
  -- In a checkout, a spec's `require 'test'` runs this file again and still
  -- sees the script's `arg`; the run already in progress tells it apart.
  local cli = __mods._test_cli("test.cli")
  if not cli.running() then os.exit(cli.main(arg)) end
end

local runner = __mods._test_runner("test.runner")

--- @class test
return {
  Nvim = __mods._test_nvim("test.nvim"),
  assert = __mods._test_assert("test.assert"),
  describe = runner.describe,
  it = runner.it,
  pending = runner.pending,
  before_all = runner.before_all,
  after_all = runner.after_all,
  before_each = runner.before_each,
  after_each = runner.after_each,
}

end
__mods._test = function(...) return __load("test", __entry, arg, ...) end

__mods._test_nvim = function(...)
  return __load("test.nvim", function(...)
---@type string[]
local arg = {}
---@diagnostic disable: global-in-non-module

local coverage = __mods._test_coverage("test.coverage")

--- Nvim remote-control helper.
--- Spawns a child `nvim --headless --embed` with RPC on stdio,
--- drives it via msgpack-RPC, and snapshots the screen grid.
---
--- This child is headless but is NOT subject to the limitations of the host
--- process running the specs: it has a real event loop driven by RPC, so `TextChanged`/
--- `TextChangedI` autocmds fire naturally from real input, and programmatic
--- `:startinsert` genuinely enters insert mode. The mode change (and any
--- scheduled work) is only observable across an RPC round-trip (a later `run`/
--- `request`), NOT within the same `run` that issued it - the round-trip is the
--- event-loop flush point. See AGENTS.md's "Test environment" section for the
--- full host/child distinction.

--- @class test.Nvim
--- @field chan integer  the job id, which `rpc = true` also makes the channel id
local Nvim = {}
Nvim.__index = Nvim

--- @class test.NvimStartOpts
--- @field columns? integer
--- @field rows? integer
--- @field rtp? string  appended to the child's runtimepath (default: the cwd)
--- @field env? table<string, string>  added to the child's environment

--- @param opts? test.NvimStartOpts
--- @return test.Nvim
function Nvim.start(opts)
  opts = opts or {}
  --- @cast opts test.NvimStartOpts

  --- @type string[]
  local argv = { vim.v.progpath, unpack(coverage.argv()) }
  vim.list_extend(argv, { '--headless', '--embed', '-n', '-u', 'NORC' })
  if opts.columns then
    vim.list_extend(argv, { '--cmd', ('set columns=%d'):format(opts.columns) })
  end
  if opts.rows then vim.list_extend(argv, { '--cmd', ('set lines=%d'):format(opts.rows) }) end

  local chan = vim.fn.jobstart(argv, { rpc = true, env = opts.env })
  if chan <= 0 then error('jobstart failed: ' .. chan, 2) end
  local self = setmetatable({ chan = chan }, Nvim)

  -- No readiness wait is needed: a request sent before the child is ready waits
  -- in the pipe until the child reads it. 100 starts, each followed at once by
  -- a request, all succeeded.

  -- Add repo to child rtp.
  local rtp = opts.rtp or vim.fn.getcwd()
  self:request('nvim_command', 'set rtp+=' .. vim.fn.escape(rtp, ' '))

  return self
end

--- Run `nvim -l <path> <args...>` under the suite's own Neovim, and wait for it
--- to exit. A script that owns its process (its stdout, its exit status) cannot
--- run in an `--embed` child, because the child's stdio is the RPC channel.
--- `-l` already skips the user's config, plugins, and shada, so the command
--- needs no isolating flags.
--- @param path string
--- @param args? string[]  the script's `arg[1]`, `arg[2]`, ...
--- @param opts? vim.SystemOpts  passed to `vim.system`; `text` defaults to true
--- @return vim.SystemCompleted
function Nvim.script(path, args, opts)
  local cmd = { vim.v.progpath, unpack(coverage.argv()) }
  vim.list_extend(cmd, { '-l', path, unpack(args or {}) })
  return vim.system(cmd, vim.tbl_extend('keep', opts or {}, { text = true })):wait()
end

--- @param method string
--- @param ... any
function Nvim:request(method, ...) return vim.rpcrequest(self.chan, method, ...) end

--- @param method string
--- @param ... any
function Nvim:notify(method, ...) vim.rpcnotify(self.chan, method, ...) end

--- Run a function inside the child and return its result.
--- The function is serialized via `string.dump` - upvalues are NOT preserved,
--- so pass the data it needs as arguments.
--- @param f fun(...): any
--- @param ... any  arguments forwarded to `f`
--- @return any
function Nvim:run(f, ...)
  return self:request(
    'nvim_exec_lua',
    'local f = ...; return assert(loadstring(f))(select(2, ...))',
    { string.dump(f), ... }
  )
end

--------------------------------------------------------------------------------
-- Async jobs
--------------------------------------------------------------------------------

--- The result of one `run_async` job: the value passed to `done`, or the error
--- the job raised. It is settled at most once.
--- @class test.Pending
--- @field settled boolean
--- @field ok boolean?  false when the job raised
--- @field value any  the value passed to `done`, or the job's error
--- @field listeners fun(ok: boolean, value: any)[]
local Pending = {}
Pending.__index = Pending

-- The child reports back by running a Lua string in the host. That string sees
-- only host globals, because a bundled module cannot be reached by `require`,
-- so open jobs live in one global table keyed by id.
_G.__test_nvim_pending = _G.__test_nvim_pending or {}
local next_id = 0

--- Only the first result counts, because a second `done` must not change a
--- value the host may already have read.
--- @param ok boolean
--- @param value any
function Pending:settle(ok, value)
  if self.settled then return end
  self.settled, self.ok, self.value = true, ok, value
  for _, cb in ipairs(self.listeners) do
    cb(ok, value)
  end
  self.listeners = {}
end

--- Block until the job settles, and return its value. Raises when the job
--- raised, or when it has not settled after `timeout_ms` (default 2000).
--- @param timeout_ms? integer
--- @return any
function Pending:wait(timeout_ms)
  timeout_ms = timeout_ms or 2000
  if not vim.wait(timeout_ms, function() return self.settled end, 1) then
    error(('run_async: no result after %d ms'):format(timeout_ms), 2)
  end
  if not self.ok then error('run_async: the child raised: ' .. tostring(self.value), 2) end
  return self.value
end

--- Call `cb(ok, value)` once the job settles, without blocking. `ok` is false
--- when the job raised, and `value` is then its error. The host handles the
--- child's result only while its own event loop runs, i.e., inside some
--- `vim.wait`. An error raised by `cb` surfaces in that RPC handler, not in the
--- spec, so `cb` should record what it saw and leave assertions to the spec.
--- @param cb fun(ok: boolean, value: any)
function Pending:on_settled(cb)
  -- A job that already settled still calls back on a later tick, so `cb`
  -- never runs before the line after `on_settled`, whichever finished first.
  if self.settled then
    vim.schedule(function()
      cb(self.ok --[[@as boolean]], self.value)
    end)
    return
  end
  table.insert(self.listeners, cb)
end

--- Start a function inside the child without blocking the host, and return
--- its pending result. The function receives a `done` callback; the value
--- passed to `done` settles the result, and so does an error raised before it.
--- The function is `string.dump`'d, so it cannot capture upvalues - use child
--- globals for state it must read.
--- @param f fun(done: fun(value?: any))
--- @return test.Pending
function Nvim:run_async(f)
  next_id = next_id + 1
  local id = next_id
  local pending = setmetatable({ settled = false, listeners = {} }, Pending)
  _G.__test_nvim_pending[id] = pending

  self:notify(
    'nvim_exec_lua',
    [[
      local code, id = ...
      -- A notification, not a request, so the child never blocks on a host
      -- that is itself blocked.
      local function settle(ok, value)
        vim.rpcnotify(1, 'nvim_exec_lua', [=[
          local id, ok, value = ...
          local pending = _G.__test_nvim_pending[id]
          _G.__test_nvim_pending[id] = nil
          if pending then pending:settle(ok, value) end
        ]=], { id, ok, value })
      end
      -- An error raised before `done` becomes the job's result, so the host
      -- sees it instead of a silent timeout.
      local ok, err = pcall(function()
        assert(loadstring(code))(function(value) settle(true, value) end)
      end)
      if not ok then settle(false, err) end
    ]],
    { string.dump(f), id }
  )

  return pending
end

--------------------------------------------------------------------------------
-- Input, screen, and waiting
--------------------------------------------------------------------------------

--- Type keys into the child nvim, auto-translating key-notation.
--- Simpler than feedkeys: no mode, no escape_ks - just virtual typing.
--- @param keys string  key notation (e.g. "ihello\<Esc>")
function Nvim:input(keys)
  local translated = self:request('nvim_replace_termcodes', keys, true, true, true)
  return self:request('nvim_input', translated)
end

--- Read the rendered grid, one string per row, status and command lines
--- included.
--- @return string[]
function Nvim:screen()
  return self:run(function()
    vim.cmd 'redraw!'
    local lines = {}
    for r = 1, vim.o.lines do
      local row = {}
      for c = 1, vim.o.columns do
        row[c] = vim.fn.screenstring(r, c)
      end
      lines[r] = table.concat(row)
    end
    return lines
  end) --[[@as string[] ]]
end

--- Wait until the work already queued with `vim.schedule` in the child has
--- run. Scheduled callbacks run in order, so a `done` scheduled now fires only
--- after that work. Raises after `timeout_ms` (default 2000).
--- @param timeout_ms? integer
function Nvim:drain(timeout_ms)
  self:run_async(function(done) vim.schedule(done) end):wait(timeout_ms)
end

--- Poll a child-side predicate until it returns true, and raise with `msg`
--- once `timeout_ms` (default 2000) passes.
---
--- Each attempt is its own RPC round trip, because the round trip - not an
--- in-child wait - is what lets the child's event loop dispatch pending work:
--- on some versions a single request's in-child wait never reaches that
--- checkpoint. `pred` is `string.dump`'d, so it cannot capture upvalues.
--- @param pred fun(): boolean
--- @param timeout_ms? integer
--- @param msg? string
function Nvim:wait_until(pred, timeout_ms, msg)
  timeout_ms = timeout_ms or 2000
  local deadline = vim.uv.now() + timeout_ms
  repeat
    if self:run(pred) then return end
    vim.wait(10)
  until vim.uv.now() >= deadline
  error(msg or ('wait_until: the predicate did not hold within %d ms'):format(timeout_ms), 2)
end

--- Stop the child, and wait for it to exit. Safe to call more than once.
function Nvim:stop()
  -- A child that already exited, e.g. on a second stop, has nothing to close.
  if vim.fn.jobwait({ self.chan }, 0)[1] ~= -1 then return end
  -- Closing the channel makes the child exit normally, which fires its
  -- `VimLeavePre`, where a coverage run writes the child's hits; waiting
  -- for the exit makes those hits complete before the run reads them. A child
  -- stuck in a busy loop never reads the close, so after the same 2000 ms that
  -- `wait_until` allows by default, it is killed without its hits.
  vim.fn.chanclose(self.chan)
  if vim.fn.jobwait({ self.chan }, 2000)[1] == -1 then vim.fn.jobstop(self.chan) end
end

return Nvim

  end, ...)
end

__mods._test_runner = function(...)
  return __load("test.runner", function(...)
---@type string[]
local arg = {}
--- Spec collection and running. Loading a spec file runs its `describe`
--- bodies immediately, which builds a tree of scopes; each `it` only records
--- its function. Running then walks the tree in order: each scope runs its
--- `before_all` hooks before its first case and its `after_all` hooks after its
--- last, and each case runs inside its scopes' `before_each` and `after_each`
--- hooks.
local M = {}

--------------------------------------------------------------------------------
-- The tree
--------------------------------------------------------------------------------

--- @class test.runner.Scope
--- @field name string
--- @field parent test.runner.Scope?
--- @field before_all fun()[]
--- @field after_all fun()[]
--- @field before_each fun()[]
--- @field after_each fun()[]
--- @field children (test.runner.Scope|test.runner.Case)[]

--- @class test.runner.Case
--- @field name string
--- @field parent test.runner.Scope
--- @field fn fun()?  nil for a pending case

-- The scope `describe`, `it`, and the hooks add to, while a spec file loads.
local collecting --- @type test.runner.Scope?

--- @param name string
--- @param parent test.runner.Scope?
--- @return test.runner.Scope
local function new_scope(name, parent)
  return {
    name = name,
    parent = parent,
    before_all = {},
    after_all = {},
    before_each = {},
    after_each = {},
    children = {},
  }
end

--- @param fn_name string
--- @return test.runner.Scope
local function current_scope(fn_name)
  if collecting then return collecting end
  error(fn_name .. ': no spec run is active; run spec files with `nvim -l <test.lua>`', 3)
end

--- Open a scope named `name` and collect what `fn` declares inside it.
--- @param name string
--- @param fn fun()
function M.describe(name, fn)
  local parent = current_scope 'describe'
  local scope = new_scope(name, parent)
  table.insert(parent.children, scope)
  collecting = scope
  -- The parent is restored even when `fn` raises, so the rest of the file is
  -- not collected into a scope that never closed. The error still propagates
  -- and fails the file.
  local ok, err = pcall(fn)
  collecting = parent
  if not ok then error(err, 0) end
end

--- Declare a case. It runs after the whole file has been collected.
--- @param name string
--- @param fn fun()
function M.it(name, fn)
  local scope = current_scope 'it'
  if type(fn) ~= 'function' then
    error(('it: %q needs a function; use pending for a case without one'):format(name), 2)
  end
  table.insert(scope.children, { name = name, parent = scope, fn = fn })
end

--- Declare a case that is reported as pending instead of run.
--- @param name string
function M.pending(name)
  local scope = current_scope 'pending'
  table.insert(scope.children, { name = name, parent = scope })
end

--- Run `fn` once, before the first case in the current scope runs, nested
--- scopes included.
--- @param fn fun()
function M.before_all(fn) table.insert(current_scope('before_all').before_all, fn) end

--- Run `fn` once, after the last case in the current scope has run, nested
--- scopes included, even when a case or a `before_all` hook failed.
--- @param fn fun()
function M.after_all(fn) table.insert(current_scope('after_all').after_all, fn) end

--- Run `fn` before each case in the current scope, nested scopes included.
--- @param fn fun()
function M.before_each(fn) table.insert(current_scope('before_each').before_each, fn) end

--- Run `fn` after each case in the current scope, nested scopes included,
--- even when the case failed.
--- @param fn fun()
function M.after_each(fn) table.insert(current_scope('after_each').after_each, fn) end

--------------------------------------------------------------------------------
-- Names and errors
--------------------------------------------------------------------------------

--- The names of a node's enclosing scopes and its own, joined by spaces. The
--- file's root scope has no name of its own, so its cases start at their
--- first `describe`.
--- @param node test.runner.Scope|test.runner.Case
--- @return string
local function full_name(node)
  local names = {}
  local current = node --- @type (test.runner.Scope|test.runner.Case)?
  while current and current.parent do
    table.insert(names, 1, current.name)
    current = current.parent
  end
  return table.concat(names, ' ')
end

--- Format an error for the report. The message comes first; traceback frames
--- follow only when they name the spec file, because frames inside the
--- library or a bundle point at code the reader did not write.
--- @param err any
--- @param trace string
--- @param path string
--- @return string
local function describe_error(err, trace, path)
  local message = type(err) == 'string' and err or vim.inspect(err)
  local frames = {}
  for line in trace:gmatch '[^\n]+' do
    if line:find(path, 1, true) then frames[#frames + 1] = line end
  end
  if #frames == 0 then return message end
  return message .. '\n' .. table.concat(frames, '\n')
end

--- Call `fn`, and return whether it succeeded and, when it did not, the
--- formatted error.
--- @param fn function
--- @param path string
--- @return boolean ok, string? err
local function protect(fn, path)
  return xpcall(fn, function(e) return describe_error(e, debug.traceback('', 2), path) end)
end

--------------------------------------------------------------------------------
-- The report
--------------------------------------------------------------------------------

--- @class test.runner.Failure
--- @field name string
--- @field message string  the error, with the traceback frames in the spec file

--- A case that takes longer than this prints its time beside its name, so the
--- slow cases stand out. 75 ms is mocha's default for a slow test.
local SLOW_MS = 75

--- The run's counts and its output: each outcome is counted and printed in
--- one step, so the two cannot disagree.
--- @class test.runner.Report
--- @field counts { passed: integer, failed: integer, pending: integer }
--- @field failures test.runner.Failure[]
--- @field paint test.color.Paint
local Report = {}
Report.__index = Report

--- @param paint test.color.Paint
--- @return test.runner.Report
function Report.new(paint)
  return setmetatable(
    { counts = { passed = 0, failed = 0, pending = 0 }, failures = {}, paint = paint },
    Report
  )
end

--- @param path string
function Report:file(path) io.stdout:write(self.paint('bold', path), '\n') end

--- The text after a case's name: its time, dim, when it ran longer than
--- `SLOW_MS`, and nothing otherwise.
--- @param ms number?  nil for a case that never ran, e.g. under a failed before_all
--- @return string
function Report:duration(ms)
  if not ms then return '' end
  -- Comparing the rounded time keeps the rule and the printed number in
  -- agreement: 75.4 ms would otherwise print as a slow `(75ms)`.
  local shown = math.floor(ms + 0.5)
  if shown <= SLOW_MS then return '' end
  return ' ' .. self.paint('dim', ('(%dms)'):format(shown))
end

--- @param name string
--- @param ms number  the case's time, with its before_each and after_each hooks
function Report:pass(name, ms)
  self.counts.passed = self.counts.passed + 1
  io.stdout:write('  ', self.paint('green', '✓'), ' ', name, self:duration(ms), '\n')
end

--- @param name string
--- @param message string
--- @param ms? number  the case's time, with its hooks; nil when it never ran
function Report:fail(name, message, ms)
  self.counts.failed = self.counts.failed + 1
  table.insert(self.failures, { name = name, message = message })
  io.stdout:write('  ', self.paint('red', '✗'), ' ', name, self:duration(ms), '\n')
end

--- A spec file that failed to load or to collect: one failure, named after
--- the file.
--- @param path string
--- @param message string
function Report:load_error(path, message)
  self.counts.failed = self.counts.failed + 1
  table.insert(self.failures, { name = path, message = message })
  io.stdout:write('  ', self.paint('red', '✗'), ' (the file did not load)\n')
end

--- @param name string
function Report:pending(name)
  self.counts.pending = self.counts.pending + 1
  io.stdout:write('  ', self.paint('yellow', '- ' .. name .. ' (pending)'), '\n')
end

--- Color a failure message's diff: `-` lines red, `+` lines green, and the
--- `--- got` and `+++ want` headers dim.
--- @param message string
--- @return string
function Report:diff_colors(message)
  local lines = {}
  for line in (message .. '\n'):gmatch '(.-)\n' do
    if line == '--- got' or line == '+++ want' then
      line = self.paint('dim', line)
    elseif line:sub(1, 2) == '- ' then
      line = self.paint('red', line)
    elseif line:sub(1, 2) == '+ ' then
      line = self.paint('green', line)
    end
    lines[#lines + 1] = line
  end
  return table.concat(lines, '\n')
end

--- Print every failure in full, then the counts.
--- @param seconds number
function Report:summary(seconds)
  for _, failure in ipairs(self.failures) do
    io.stdout:write(
      '\n',
      self.paint('red', self.paint('bold', '✗ ' .. failure.name)),
      '\n',
      self:diff_colors(failure.message),
      '\n'
    )
  end
  --- @param count integer
  --- @param word string
  --- @param style test.color.Style
  local function count_of(count, word, style)
    local text = ('%d %s'):format(count, word)
    return count > 0 and self.paint(style, text) or text
  end
  io.stdout:write(
    '\n',
    count_of(self.counts.passed, 'passed', 'green'),
    ', ',
    count_of(self.counts.failed, 'failed', 'red'),
    ', ',
    count_of(self.counts.pending, 'pending', 'yellow'),
    ('%s\n'):format(self.paint('dim', (' in %.2fs'):format(seconds)))
  )
end

--------------------------------------------------------------------------------
-- Running
--------------------------------------------------------------------------------

--- The scopes from the file's root down to the case's own scope.
--- @param case test.runner.Case
--- @return test.runner.Scope[]
local function scopes_of(case)
  local scopes = {}
  local scope = case.parent --- @type test.runner.Scope?
  while scope do
    table.insert(scopes, 1, scope)
    scope = scope.parent
  end
  return scopes
end

--- Run one case with its `before_each` and `after_each` hooks, and record its
--- outcome. Before-hooks run from the outermost scope inward, and a failing
--- one skips the rest and the case; after-hooks run from the innermost scope
--- outward, always.
--- @param case test.runner.Case
--- @param path string
--- @param report test.runner.Report
local function run_case(case, path, report)
  local name = full_name(case)
  if not case.fn then return report:pending(name) end

  local started = vim.uv.hrtime()
  local errors = {}
  --- @param fn fun()
  --- @return boolean
  local function attempt(fn)
    local ok, err = protect(fn, path)
    if not ok then errors[#errors + 1] = err end
    return ok
  end

  local scopes = scopes_of(case)
  local ready = true
  for _, scope in ipairs(scopes) do
    for _, hook in ipairs(scope.before_each) do
      ready = ready and attempt(hook)
    end
  end
  if ready then attempt(case.fn) end
  for i = #scopes, 1, -1 do
    for _, hook in ipairs(scopes[i].after_each) do
      attempt(hook)
    end
  end

  local ms = (vim.uv.hrtime() - started) / 1e6
  if #errors == 0 then return report:pass(name, ms) end
  report:fail(name, table.concat(errors, '\n\n'), ms)
end

--- Whether `filter`, a plain substring of the full case name, selects `case`.
--- @param case test.runner.Case
--- @param filter string?
--- @return boolean
local function selected(case, filter)
  return not filter or full_name(case):find(filter, 1, true) ~= nil
end

--- The cases under `scope`, nested scopes included, that `filter` selects.
--- @param scope test.runner.Scope
--- @param filter string?
--- @param out? test.runner.Case[]
--- @return test.runner.Case[]
local function selected_cases(scope, filter, out)
  out = out or {}
  for _, child in ipairs(scope.children) do
    if child.children then
      selected_cases(child --[[@as test.runner.Scope]], filter, out)
    elseif
      selected(child --[[@as test.runner.Case]], filter)
    then
      out[#out + 1] = child --[[@as test.runner.Case]]
    end
  end
  return out
end

--- Run a scope's selected cases between its `before_all` and `after_all`
--- hooks. A scope with nothing selected runs neither hook. A failing
--- `before_all` skips the rest of the scope and fails each selected case with
--- its error; `after_all` still runs, so it can undo a partial setup.
--- @param scope test.runner.Scope
--- @param path string
--- @param filter string?
--- @param report test.runner.Report
local function run_scope(scope, path, filter, report)
  local cases = selected_cases(scope, filter)
  if #cases == 0 then return end
  -- A hook failure is reported under the scope's name, or the file's for the
  -- root scope.
  local scope_name = scope.parent and full_name(scope) or path

  local setup_err --- @type string?
  for _, hook in ipairs(scope.before_all) do
    local ok, err = protect(hook, path)
    if not ok then
      setup_err = ('before_all in %s failed:\n%s'):format(scope_name, err)
      break
    end
  end

  if setup_err then
    for _, case in ipairs(cases) do
      if case.fn then
        report:fail(full_name(case), setup_err)
      else
        report:pending(full_name(case))
      end
    end
  else
    for _, child in ipairs(scope.children) do
      if child.children then
        run_scope(child --[[@as test.runner.Scope]], path, filter, report)
      elseif
        selected(child --[[@as test.runner.Case]], filter)
      then
        run_case(child --[[@as test.runner.Case]], path, report)
      end
    end
  end

  for _, hook in ipairs(scope.after_all) do
    local ok, err = protect(hook, path)
    if not ok then
      report:fail(scope_name .. ' (after_all)', err --[[@as string]])
    end
  end
end

--- Load one spec file and collect its tree. A file that fails to load or to
--- collect is reported as one failure, and its cases do not run.
--- @param path string
--- @return test.runner.Scope?, string?
local function collect(path)
  local root = new_scope(path)
  local chunk, load_err = loadfile(path)
  if not chunk then return nil, load_err end
  collecting = root
  local ok, err = protect(chunk, path)
  collecting = nil
  if not ok then return nil, err end
  return root
end

--- @param path string
--- @param filter string?  a plain substring of the full case name
--- @param report test.runner.Report
local function run_file(path, filter, report)
  -- Modules a file loads are dropped after it, so one file's module state
  -- (a cache, a counter, a patched function) cannot leak into the next.
  local loaded_before = {}
  for name in pairs(package.loaded) do
    loaded_before[name] = true
  end

  report:file(path)
  local root, err = collect(path)
  if root then
    run_scope(root, path, filter, report)
  else
    report:load_error(path, err --[[@as string]])
  end

  for name in pairs(package.loaded) do
    if not loaded_before[name] then package.loaded[name] = nil end
  end
end

--- Run every file in order, print a report, and return it.
--- @param paths string[]
--- @param opts { filter?: string, paint: test.color.Paint }
--- @return test.runner.Report
function M.run(paths, opts)
  local report = Report.new(opts.paint)
  local started = vim.uv.hrtime()
  for _, path in ipairs(paths) do
    run_file(path, opts.filter, report)
  end
  report:summary((vim.uv.hrtime() - started) / 1e9)
  return report
end

return M

  end, ...)
end

